examples.code:
body {
  font-family: system-ui, sans-serif;
  line-height: 1.6;
  color: #172033;
}

h1 {
  color: #1d4ed8;
  font-size: 2rem;
  line-height: 1.15;
}

a {
  color: #1d4ed8;
  text-underline-offset: 3px;
}

li::marker {
  color: #1d4ed8;
}

.card {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 1rem 1.25rem;
}

.card h2 {
  margin-top: 0;
}

ul {
  list-style: none;
  padding: 0;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  overflow: hidden;
}

li {
  padding: 0.6rem 1rem;
  border-bottom: 1px solid #e2e8f0;
}

li:nth-child(even) {
  background: #f1f5f9;
}

li:last-child {
  border-bottom: 0;
}

li:hover {
  background: #dbeafe;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

.card {
  max-width: 22rem;
  padding: 1.25rem 1.5rem;
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  box-shadow:
    0 1px 2px rgb(0 0 0 / 8%),
    0 8px 24px rgb(0 0 0 / 8%);
}

.card h2 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
  line-height: 1.2;
}

.card p {
  margin: 0 0 1rem;
  color: #475569;
}

.card button {
  padding: 0.5rem 1rem;
  border: 0;
  border-radius: 6px;
  background: #1d4ed8;
  color: white;
}

button {
  padding: 0.6rem 1.25rem;
  border: 2px solid #1d4ed8;
  border-radius: 9999px;
  background: #1d4ed8;
  color: white;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 200ms ease-out, transform 200ms ease-out, box-shadow 200ms ease-out;
}

button:hover {
  background: #1e3a8a;
  border-color: #1e3a8a;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgb(29 78 216 / 35%);
}

button:active {
  transform: translateY(0);
  box-shadow: none;
}

button:focus-visible {
  outline: 3px solid #f59e0b;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  button {
    transition: none;
  }
}

body {
  font-family: Georgia, serif;
  font-size: clamp(1rem, 0.9rem + 0.4vw, 1.2rem);
  line-height: 1.6;
}

h1 {
  font-size: clamp(1.75rem, 1rem + 3vw, 3.25rem);
  line-height: 1.1;
  letter-spacing: -0.01em;
}

h2 {
  font-size: clamp(1.25rem, 1rem + 1.2vw, 1.75rem);
  line-height: 1.2;
}

p {
  max-width: 65ch;
}
